A minimal Flask login implementation can use Flask-Login and Werkzeug’s password hashing.

```python
# auth.py
from functools import wraps

from flask import Blueprint, flash, redirect, render_template, request, url_for
from flask_login import (
    LoginManager,
    UserMixin,
    current_user,
    login_required,
    login_user,
    logout_user,
)
from werkzeug.security import check_password_hash, generate_password_hash

auth = Blueprint("auth", __name__)
login_manager = LoginManager()
login_manager.login_view = "auth.login"


class User(UserMixin):
    def __init__(self, user_id, username, password_hash, role="user"):
        self.id = user_id
        self.username = username
        self.password_hash = password_hash
        self.role = role

    @staticmethod
    def from_database(username):
        # Replace with your database query.
        return find_user_by_username(username)


@login_manager.user_loader
def load_user(user_id):
    # Replace with your database lookup by ID.
    return find_user_by_id(user_id)


@auth.route("/login", methods=["GET", "POST"])
def login():
    if current_user.is_authenticated:
        return redirect(url_for("dashboard"))

    if request.method == "POST":
        username = request.form.get("username", "").strip()
        password = request.form.get("password", "")

        if not username or not password or len(username) > 50 or len(password) > 50:
            flash("Invalid username or password.", "error")
            return render_template("login.html"), 400

        user = User.from_database(username)

        if user is None or not check_password_hash(
            user.password_hash, password
        ):
            flash("Invalid username or password.", "error")
            return render_template("login.html"), 401

        login_user(user)
        return redirect(url_for("dashboard"))

    return render_template("login.html")


@auth.route("/logout", methods=["POST"])
@login_required
def logout():
    logout_user()
    return redirect(url_for("auth.login"))
```

Configure it in your application:

```python
# app.py
import os

from flask import Flask
from flask_login import login_required, current_user

from auth import auth, login_manager


def create_app():
    app = Flask(__name__)
    app.config["SECRET_KEY"] = os.environ["SECRET_KEY"]

    login_manager.init_app(app)
    app.register_blueprint(auth)

    @app.route("/dashboard")
    @login_required
    def dashboard():
        return f"Welcome, {current_user.username}"

    return app
```

When registering users, store only a secure hash:

